// Failure injection for the watchdog only; never used by the browser execution.
import fs from 'node:fs';
import { syncBuiltinESMExports } from 'node:module';
const write = fs.writeFileSync;
fs.writeFileSync = function (...args: Parameters<typeof fs.writeFileSync>) {
  if (typeof args[1] === 'string' && args[1].includes('"outcome": "command-passed"'))
    throw new Error('Injected final-inventory write failure');
  return write(...args);
};
syncBuiltinESMExports();
process.argv[1] = '/tmp/spn135-local-watchdog.ts';
void import('./spn135-local-watchdog.ts');

