import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
if (process.argv[2] === 'detached-child') {
  writeFileSync('/tmp/spn135-local-control-child.json', JSON.stringify({ pid: process.pid, parent: process.ppid }));
  setInterval(() => {}, 1000);
} else {
  const child = spawn(process.execPath, [process.argv[1], 'detached-child'], { detached: true, stdio: 'ignore' });
  child.unref();
  setTimeout(() => process.exit(0), 1500);
}

