import assert from 'node:assert/strict';
import test from 'node:test';
import {ownedProcesses,sameProcess} from './spn135-local-processes.ts';
const row=(pid:number,parent:number,started='Mon Nov 2 14:00:00 2026',command='owned')=>({pid,parent,group:pid,rssKiB:1,started,command});
test('ownership follows descendants and retained identities through reparenting only',()=>{
 const known=new Map();
 assert.deepEqual(ownedProcesses([row(10,1),row(11,10),row(12,11),row(13,1)],10,known).map(x=>x.pid),[10,11,12]);
 assert.deepEqual(ownedProcesses([row(12,1),row(14,12),row(15,1)],-1,known).map(x=>x.pid),[12,14]);
});
test('a reused PID or changed command is not owned',()=>{
 const before=row(20,1);const known=new Map([[20,before]]);
 const reused=row(20,1,'Mon Nov 2 15:00:00 2026');
 assert.equal(sameProcess(before,reused),false);
 assert.deepEqual(ownedProcesses([reused,row(21,20)],-1,known),[]);
 assert.deepEqual(ownedProcesses([row(20,1,before.started,'unrelated')],-1,known),[]);
});

spn135-local-processes.ts:
import { execFileSync } from 'node:child_process';

export interface ProcessRow {
  pid: number; parent: number; group: number; rssKiB: number; started: string; command: string;
}
export function processes(): ProcessRow[] {
  return execFileSync('ps', ['-axo', 'pid=,ppid=,pgid=,rss=,lstart=,command='], { encoding: 'utf8' })
    .trim().split('\n').map(line => {
      const match = line.match(/^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\S+\s+\S+\s+\d+\s+\S+\s+\d+)\s+(.+)$/);
      if (!match) throw new Error('Unrecognized process row');
      return { pid: +match[1], parent: +match[2], group: +match[3], rssKiB: +match[4], started: match[5], command: match[6] };
    });
}
export const sameProcess = (a: ProcessRow, b: ProcessRow) =>
  a.pid === b.pid && a.started === b.started && a.command === b.command;

export function ownedProcesses(rows: ProcessRow[], root: number, known: Map<number, ProcessRow>) {
  const owned = new Set(rows.filter(row => row.pid === root ||
    (known.has(row.pid) && sameProcess(known.get(row.pid)!, row))).map(row => row.pid));
  for (let size = -1; size !== owned.size;) {
    size = owned.size;
    for (const row of rows) if (owned.has(row.parent)) owned.add(row.pid);
  }
  const result = rows.filter(row => owned.has(row.pid));
  for (const row of result) known.set(row.pid, row);
  return result;
}

export function signalOwned(known: Map<number, ProcessRow>, signal: NodeJS.Signals, exclude: number) {
  const live = processes().filter(row => row.pid !== exclude && known.has(row.pid) &&
    sameProcess(known.get(row.pid)!, row));
  for (const row of live) {
    // Revalidate immediately before signalling; never select all newly created PIDs.
    const current = processes().find(value => sameProcess(value, row));
    if (current) try { process.kill(row.pid, signal); } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ESRCH') throw error;
    }
  }
  return live;
}

spn135-local-watchdog.ts:
import { spawn, execFileSync } from 'node:child_process';
import { writeFileSync, renameSync } from 'node:fs';
import { ownedProcesses, processes, signalOwned } from './spn135-local-processes.ts';
import type { ProcessRow } from './spn135-local-processes.ts';

const [destination, command, ...args] = process.argv.slice(2);
const started = Date.now();
const known = new Map<number, ProcessRow>();
const initial = processes().find(row => row.pid === process.pid)!;
if (initial.group !== process.pid) throw new Error('Run this watchdog through scripts/serial.ts');
if (execFileSync('sysctl', ['-n', 'kern.memorystatus_vm_pressure_level'], { encoding: 'utf8' }).trim() !== '1')
  throw new Error('Memory pressure must be normal before launch');
let peakKiB = 0;
function snapshot(outcome: string) {
  const live = ownedProcesses(processes(), process.pid, known);
  const rssKiB = live.reduce((sum, row) => sum + row.rssKiB, 0);
  peakKiB = Math.max(peakKiB, rssKiB);
  const pressure = execFileSync('sysctl', ['-n', 'kern.memorystatus_vm_pressure_level'], { encoding: 'utf8' }).trim();
  const record = { root: process.pid, started, elapsedMs: Date.now() - started, outcome, pressure,
    rssKiB, peakKiB, live, known: [...known.values()], scope: 'Observed task descendants, retaining start/command identities across reparenting; not system-wide absence' };
  // A failed update must leave the last complete ownership inventory readable.
  writeFileSync(destination + '.tmp', JSON.stringify(record, null, 2) + '\n');
  renameSync(destination + '.tmp', destination);
  return record;
}
snapshot('ready');
const child = spawn(command, args, { stdio: 'inherit' });
function abort(reason: string) {
  try { snapshot(reason); } catch (error) { console.error('Snapshot retention failed', error); }
  try { signalOwned(known, 'SIGKILL', process.pid); }
  finally { process.kill(0, 'SIGKILL'); }
}
const monitor = setInterval(() => {
  try {
    const state = snapshot('running');
    if (state.pressure !== '1' || state.rssKiB > 2 * 1024 ** 2 || state.elapsedMs > 475_000) {
      console.error('WATCHDOG ABORT: ' + JSON.stringify({ pressure: state.pressure, rssKiB: state.rssKiB, elapsedMs: state.elapsedMs }));
      abort('resource-aborted');
    }
  } catch (error) {
    console.error('WATCHDOG MONITOR FAILED', error);
    abort('monitor-failed');
  }
}, 250);
child.once('error', error => {
  clearInterval(monitor);
  console.error(error);
  try { snapshot('spawn-failed'); process.exitCode = 1; }
  catch (failure) { console.error('Final snapshot failed', failure); abort('monitor-failed'); }
});
child.once('exit', (code, signal) => {
  clearInterval(monitor);
  try {
    const state = snapshot(code === 0 ? 'command-passed' : 'command-failed');
    console.error('WATCHDOG: ' + JSON.stringify({ code, signal, elapsedMs: state.elapsedMs, peakKiB }));
    process.exitCode = code ?? 1;
  } catch (failure) { console.error('Final snapshot failed', failure); abort('monitor-failed'); }
});
